customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    total_transactions=COUNT(transactions_made),
    successful_transactions=COUNT(transactions_made.WHERE(status == "SUCCESS"))
).CALCULATE(
    customer_name=customer_name,
    success_rate=1.0 * successful_transactions / total_transactions
).ORDER_BY(success_rate.ASC())

customer_count = Customers.WHERE(
    (STARTSWITH(LOWER(name), "j")) | (ENDSWITH(LOWER(name), "ez"))
).WHERE(
    ENDSWITH(LOWER(state), "a")
).CALCULATE(customer_name=name)
result = EXAMPLE_GRAPH.CALCULATE(num_customers=COUNT(customer_count))

sell_transactions = Transactions.WHERE(
    (transaction_type == "SELL") & (date_time == "2023-04-01")
)

customer_transactions = sell_transactions.PARTITION(name="customer_group", by=customer_id).CALCULATE(
    customer_id=customer_id,
    num_transactions=COUNT(Transactions)
)

result = Customers.CALCULATE(
    _id=_id,
    name=name
).WHERE(HAS(transactions_made.WHERE(
    (transaction_type == "SELL") & (date_time == "2023-04-01")
))).TOP_K(1, by=COUNT(transactions_made.WHERE(
    (transaction_type == "SELL") & (date_time == "2023-04-01")
)).DESC()).CALCULATE(_id=_id, name=name, num_transactions=COUNT(transactions_made.WHERE(
    (transaction_type == "SELL") & (date_time == "2023-04-01")
)))

asp = Sales.WHERE(
    (YEAR(sale_date) == 2023) & (QUARTER(sale_date) == 1)
).CALCULATE(
    average_sale_price=AVG(sale_price)
)

avg_days_between_sale_and_payment = Sales.CALCULATE(
    day_difference=DATEDIFF("days", sale_date, payment.payment_date)
).CALCULATE(
    average_days=ROUND(AVG(day_difference), 2)
)

payments_made_on_weekends = PaymentsMade.WHERE(
    (vendor_name == 'Utility Company') & (ISIN(DAYOFWEEK(payment_date), (1, 7)))
).CALCULATE(num_payments=COUNT(PaymentsMade))

latest_inventory = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3) & (is_in_inventory == True)
).CALCULATE(
    latest_date=MAX(snapshot_date)
)

cars_in_inventory = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3) & (is_in_inventory == True) & (snapshot_date == latest_inventory.SINGULAR().latest_date)
).car.CALCULATE(
    car_id=_id,
    car_make=make,
    car_model=model,
    car_year=year
)

drug_ddd = Drugs.treatments_used_in.WHERE(
    HAS(treatments_used_in) == 1
).WHERE(
    HAS(drug) == 1
).WHERE(
    ISNOTNULL(end_dt) == 1
).CALCULATE(
    drug_name=drug.drug_name,
    ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
)

avg_ddd_per_drug = drug_ddd.PARTITION(name="drug_groups", by=drug_name).CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(ddd)
)

result = avg_ddd_per_drug.CALCULATE(drug_name=drug_name, avg_ddd=avg_ddd)

patient_count = Patients.WHERE(
    (ENDSWITH(email, "@gmail.com")) | (ENDSWITH(email, "@yahoo.com"))
).CALCULATE(num_patients=COUNT(Patients))

from datetime import datetime, timedelta

current_date = datetime.now()
six_months_ago = current_date - timedelta(days=180)

alice_treatments = patients.WHERE(
    (first_name == "Alice") & (last_name == "Patient")
).treatments_received.WHERE(
    (start_dt >= six_months_ago.date()) & (start_dt < current_date.date())
)

result = patients.WHERE(
    (first_name == "Alice") & (last_name == "Patient")
).CALCULATE(
    num_treatments=COUNT(alice_treatments)
)

doctors_filtered = Doctors.WHERE(
    (STARTSWITH(LOWER(first_name), "j")) | (CONTAINS(LOWER(last_name), "son"))
).CALCULATE(first_name=first_name, last_name=last_name, specialty=speciality)

overall_d7d100pir = Outcomes.WHERE(
    HAS(day7_pasi_score) == 1 & HAS(day100_pasi_score) == 1
).CALCULATE(
    d7d100pir=(AVG(day100_pasi_score) - AVG(day7_pasi_score)) / AVG(day7_pasi_score) * 100
).SINGULAR()

from datetime import datetime

current_year = datetime.now().year
average_age = Patients.WHERE(
    (gender == "Male") & (ins_type == "Private")
).CALCULATE(
    age=current_year - YEAR(date_of_birth)
).CALCULATE(
    average_age=AVG(age)
)

us_users_unread_promotional_notifications = Users.WHERE(
    LOWER(country) == 'us'
).CALCULATE(
    username=username,
    num_unread_promotional_notifications=COUNT(notifications.WHERE(
        (notification_type == 'promotional') & (status == 'unread')
    ))
)

from datetime import datetime, timedelta

end_date = datetime.now()
start_date = end_date - timedelta(days=150)

top_merchants = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & (created_at >= start_date) & (created_at <= end_date)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & (created_at >= start_date) & (created_at <= end_date)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & (created_at >= start_date) & (created_at <= end_date)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

result = Merchants.WHERE(
    (status == 'active') & (CONTAINS(category, 'retail'))
).balances.WHERE(updated_at == TODAY()).CALCULATE(median_balance=MEDIAN(balance))

users_without_notifications = Users.WHERE(
    HASNOT(notifications.WHERE(
        (created_at >= created_at) & (created_at <= DATETIME(created_at, "+1 year"))
    ))
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)

region_order_values_1996 = regions.WHERE(
  HAS(nations.customers.orders) == 1
).CALCULATE(
    region_name=name,
    total_order_value=SUM(nations.customers.orders.WHERE(YEAR(order_date) == 1996).lines.extended_price * (1 - nations.customers.orders.WHERE(YEAR(order_date) == 1996).lines.discount))
).TOP_K(1, by=total_order_value.DESC())

customers_1996_not_1997 = customers.WHERE(
    HAS(orders.WHERE(YEAR(order_date) == 1996)) == 1
).WHERE(
    HASNOT(orders.WHERE(YEAR(order_date) == 1997)) == 1
).CALCULATE(
    customer_key=key,
    customer_name=name,
    total_spent=SUM(orders.total_price),
    months_since_last_order=DATEDIFF("months", MAX(orders.order_date), "now")
).WHERE(total_spent > 1000).ORDER_BY(total_spent.DESC())
